create table public.term_reports(id uuid primary key default gen_random_uuid(),classroom_id uuid not null references public.classrooms(id) on delete cascade,student_id uuid not null references public.profiles(id) on delete cascade,created_by uuid references public.profiles(id) on delete set null,title text not null check(length(title) between 1 and 100),teacher_note text not null check(length(teacher_note)<=2000),snapshot jsonb not null check(octet_length(snapshot::text)<=200000),version integer not null check(version>0),published_at timestamptz,created_at timestamptz not null default now(),unique(classroom_id,student_id,version));
create index term_reports_student_time_idx on public.term_reports(student_id,created_at desc,id);create index term_reports_creator_idx on public.term_reports(created_by);
alter table public.term_reports enable row level security;revoke all on public.term_reports from public,anon,authenticated;grant select on public.term_reports to authenticated;grant all on public.term_reports to service_role;
create policy term_report_read on public.term_reports for select to authenticated using ((select private.data_session()) and (private.is_teacher(classroom_id) or (student_id=(select auth.uid()) and published_at is not null and private.is_active_student(classroom_id))));
create function private.immutable_term_report() returns trigger language plpgsql set search_path='' as $$begin if (to_jsonb(old)-'published_at'-'created_by') is distinct from (to_jsonb(new)-'published_at'-'created_by') or (old.created_by is distinct from new.created_by and (new.created_by is not null or exists(select 1 from public.profiles where id=old.created_by))) then raise exception 'BF_REPORT_IMMUTABLE';end if;return new;end $$;
revoke all on function private.immutable_term_report() from public,anon,authenticated;
create trigger term_report_immutable before update on public.term_reports for each row execute function private.immutable_term_report();
create function public.growth_report_state(p_classroom uuid,p_student uuid,p_from date default null,p_until date default null,p_page integer default 1) returns jsonb language plpgsql stable security invoker set search_path='' as $$
declare result jsonb;
begin
 if not private.data_session() or not exists(select 1 from public.enrollments where classroom_id=p_classroom and student_id=p_student) or not(private.is_teacher(p_classroom) or (auth.uid()=p_student and private.is_active_student(p_classroom))) then raise exception 'BF_FORBIDDEN';end if;
 if (p_from is null)<>(p_until is null) or p_from>p_until or p_until-p_from>1096 or p_page is null or p_page not between 1 and 100000 then raise exception 'BF_INVALID_INPUT';end if;
 with readings as materialized(select * from public.reading_logs where classroom_id=p_classroom and student_id=p_student and (p_from is null or read_on between p_from and p_until)),
 writings as materialized(select s.* from public.submissions s join public.assignments a on a.id=s.assignment_id where a.classroom_id=p_classroom and s.student_id=p_student and (p_from is null or (s.created_at at time zone 'Asia/Seoul')::date between p_from and p_until)),
 completed as materialized(select distinct on(assignment_id) * from writings where status='completed' order by assignment_id,version desc),
 events as materialized(select * from public.activity_events where classroom_id=p_classroom and student_id=p_student and (p_from is null or (created_at at time zone 'Asia/Seoul')::date between p_from and p_until))
 select jsonb_build_object('asOf',now(),'student',(select jsonb_build_object('id',id,'name',display_name) from public.profiles where id=p_student),'classroom',(select jsonb_build_object('id',id,'name',name,'year',academic_year,'semester',semester,'termState',term_state) from public.classrooms where id=p_classroom),'from',p_from,'until',p_until,'page',p_page,
 'counts',jsonb_build_object('readingLogs',(select count(*) from readings),'completedBooks',(select count(distinct coalesce(nullif(btrim(book->>'isbn'),''),lower(btrim(book->>'title'))||'|'||lower(btrim(coalesce(book->>'author',''))))) from readings where status='completed'),'completedMissions',(select count(*) from completed),'resubmissions',(select count(*) from writings where version>1),'feedback',(select count(*) from public.feedback f join writings w on w.id=f.submission_id),'xp',coalesce((select sum(xp) from events),0),'attendanceDays',(select count(distinct (created_at at time zone 'Asia/Seoul')::date) from events where kind='attendance')),
 'badges',coalesce((select jsonb_agg(to_jsonb(x)) from(select code,period_key,evidence_count from public.achievement_badges where classroom_id=p_classroom and student_id=p_student and (p_from is null or (created_at at time zone 'Asia/Seoul')::date between p_from and p_until) order by created_at desc,id limit 100)x),'[]'),
 'candidateTotal',(select count(*) from completed),'works',coalesce((select jsonb_agg(to_jsonb(x)) from(select id,assignment_id,title,body,version,created_at from completed order by created_at desc,id limit 20 offset (p_page-1)*20)x),'[]'),
 'latestVersion',coalesce((select max(version) from public.term_reports where classroom_id=p_classroom and student_id=p_student),0)) into result;return result;
end $$;
revoke all on function public.growth_report_state(uuid,uuid,date,date,integer) from public,anon;grant execute on function public.growth_report_state(uuid,uuid,date,date,integer) to authenticated;
create function public.create_growth_report(p_classroom uuid,p_student uuid,p_from date,p_until date,p_works uuid[],p_title text,p_note text,p_publish boolean,p_confirmed boolean,p_expected_version integer,p_request_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=auth.uid();previous private.growth_term_requests;fingerprint text;state jsonb;works jsonb;result jsonb;report_id uuid;
begin if not private.data_session() or not private.is_teacher(p_classroom) then raise exception 'BF_FORBIDDEN';end if;
 if p_confirmed is distinct from true or p_request_id is null or p_expected_version is null or p_expected_version<0 or p_title is null or length(btrim(p_title)) not between 1 and 100 or p_note is null or length(p_note)>2000 or p_works is null or cardinality(p_works)>3 or p_publish is null or (select count(distinct x) from unnest(p_works)x)<>cardinality(p_works) then raise exception 'BF_INVALID_INPUT';end if;
 perform 1 from public.profiles where id=actor for update;perform 1 from public.profiles where id=p_student for update;perform 1 from public.classrooms where id=p_classroom for update;
 fingerprint:=encode(sha256(convert_to(jsonb_build_object('report',p_classroom,'student',p_student,'from',p_from,'until',p_until,'works',p_works,'title',p_title,'note',p_note,'publish',p_publish,'version',p_expected_version)::text,'UTF8')),'hex');
 select * into previous from private.growth_term_requests where actor_id=actor and request_id=p_request_id;
 if found then if previous.fingerprint<>fingerprint then raise exception 'BF_IDEMPOTENCY_CONFLICT';end if;return previous.result;end if;
 state:=public.growth_report_state(p_classroom,p_student,p_from,p_until,1);
 if (state->>'latestVersion')::integer<>p_expected_version then raise exception 'BF_REPORT_CONFLICT';end if;
 if (select count(*) from public.submissions s join public.assignments a on a.id=s.assignment_id where s.id=any(p_works) and s.student_id=p_student and a.classroom_id=p_classroom and s.status='completed' and (p_from is null or (s.created_at at time zone 'Asia/Seoul')::date between p_from and p_until))<>cardinality(p_works) then raise exception 'BF_FORBIDDEN';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'title',s.title,'body',s.body,'version',s.version,'created_at',s.created_at,'firstTitle',first.title,'firstBody',first.body,'firstDate',first.created_at) order by picked.n),'[]') into works from unnest(p_works) with ordinality picked(id,n) join public.submissions s on s.id=picked.id left join lateral(select title,body,created_at from public.submissions where assignment_id=s.assignment_id and student_id=p_student order by version limit 1) first on true;
 state:=(state-'works'-'candidateTotal'-'latestVersion'-'page')||jsonb_build_object('works',works);
 insert into public.term_reports(classroom_id,student_id,created_by,title,teacher_note,snapshot,version,published_at) values(p_classroom,p_student,actor,btrim(p_title),p_note,state,p_expected_version+1,case when p_publish then now() end) returning id into report_id;
 result:=jsonb_build_object('id',report_id,'version',p_expected_version+1);insert into private.growth_term_requests values(actor,p_request_id,fingerprint,result,now());return result;
end $$;
revoke all on function public.create_growth_report(uuid,uuid,date,date,uuid[],text,text,boolean,boolean,integer,uuid) from public,anon;grant execute on function public.create_growth_report(uuid,uuid,date,date,uuid[],text,text,boolean,boolean,integer,uuid) to authenticated;
do $$declare definition text;anchor text:='delete from public.submissions where id=any(subs);';begin
 definition:=pg_get_functiondef('public.operations_purge(uuid)'::regprocedure);if position(anchor in definition)=0 then raise exception 'Report purge anchor missing';end if;
 definition:=replace(definition,anchor,'delete from public.term_reports where student_id=r.student_id and (r.classroom_id is null or classroom_id=r.classroom_id);'||E'\n'||anchor);execute definition;
end $$;
